<button id="export">Export CSV</button>

<textarea id="csv"></textarea>

<script>
const cells = document.querySelectorAll('input[type="text"]');
const exportButton = document.getElementById('export');
const csvTextarea = document.getElementById('csv');

cells.forEach(cell => {
  cell.addEventListener('keydown', function(event) {
    if (event.key === 'Enter') {
      calculateAndCommit();
    }
  });

  cell.addEventListener('blur', calculateAndCommit);
});

exportButton.addEventListener('click', exportCSV);

function calculateAndCommit() {
  const row = this.dataset.row;
  const col = this.dataset.col;
  const formula = this.rawValue();
  let value;

  if (formula.startsWith('=')) {
    try {
      value = eval(formula);
    } catch (e) {
      value = '#ERR';
    }
  } else {
    value = parseFloat(formula) || 0;
  }

  this.setDisplayValue(value);
}


function exportCSV() {
  const csvRows = [];
  for (let i = 1; i <= 10; i++) {
    const rowValues = Array.from(cells).map(cell => cell.setDisplayValue());
    csvRows.push(rowValues.join(','));
  }
  csvTextarea.value = csvRows.join('\n');
}


function setDisplayValue(value) {
  this.value = String(value);
}

function rawValue() {
  return this.value;
}
</script>
